class KyrgyzInputMethodService :
    InputMethodService(),
    KyrgyzKeyboardEngine.Listener,
    LifecycleOwner,
    ViewModelStoreOwner,
    SavedStateRegistryOwner {

    private val lifecycleRegistry = LifecycleRegistry(this)
    private val store = ViewModelStore()
    private val savedStateController = SavedStateRegistryController.create(this)

    override val lifecycle: Lifecycle get() = lifecycleRegistry
    override val viewModelStore: ViewModelStore get() = store
    override val savedStateRegistry: SavedStateRegistry get() = savedStateController.savedStateRegistry

    private val engine: KyrgyzKeyboardEngine by lazy { KyrgyzKeyboardEngine(this) }

    // 在 Service 类中使用 = 而不是 by 委托
    private var languageState = mutableStateOf(Language.KYRGYZ)
    private var layoutState = mutableStateOf(LayoutType.DEFAULT)
    private var kyrgyzShiftState = mutableStateOf(false)
    private var englishShiftState = mutableStateOf(false)
    private var composingState = mutableStateOf("")
    private var candidatesState = mutableStateOf<List<String>>(emptyList())
    private var fontSizeState = mutableStateOf(18f)
    private var enterLabelState = mutableStateOf<String?>(null)
    private val keyFeedback by lazy { KeyFeedback(this) }

    // 当前输入框期望的回车动作（EditorInfo.imeOptions），无动作时为 null（回车即换行）
    private var editorAction: Int? = null

    override fun onCreate() {
        super.onCreate()
        savedStateController.performRestore(null)
        lifecycleRegistry.currentState = Lifecycle.State.CREATED
        KyrgyzKeyboardLayouts.forType(LayoutType.SYMBOL)
        KyrgyzKeyboardLayouts.forType(LayoutType.DEFAULT, false)
        KyrgyzKeyboardLayouts.forType(LayoutType.DIGITAL)
        EnglishKeyboardLayouts.letterLayout(false)
        PinyinKeyboardLayouts.layout
        PinyinDictionary.query("ni")
        // 柯语词库：异步加载种子表 + 用户词，注入引擎
        engine.kyrgyzWordProvider = KyrgyzDictionaryStore(this)
    }

    override fun onCreateInputView(): View {
        lifecycleRegistry.currentState = Lifecycle.State.RESUMED
        window?.window?.decorView?.let { decor ->
            decor.setViewTreeLifecycleOwner(this)
            decor.setViewTreeViewModelStoreOwner(this)
            decor.setViewTreeSavedStateRegistryOwner(this)
        }
        val composeView = ComposeView(this)
        composeView.setViewTreeLifecycleOwner(this)
        composeView.setViewTreeViewModelStoreOwner(this)
        composeView.setViewTreeSavedStateRegistryOwner(this)
        composeView.setContent {
            KyrgyzKeyboardTheme {
                // 使用 .value 获取状态值
                KeyboardRoot(
                    engine = engine,
                    language = languageState.value,
                    layout = layoutState.value,
                    kyrgyzShift = kyrgyzShiftState.value,
                    englishShift = englishShiftState.value,
                    composing = composingState.value,
                    candidates = candidatesState.value,
                    keyFontSize = fontSizeState.value,
                    enterLabel = enterLabelState.value,
                    onFeedback = { keyFeedback.perform() },
                    onStateChanged = { syncStateFromEngine() }
                )
            }
        }
        return composeView
    }

    override fun onStartInputView(info: android.view.inputmethod.EditorInfo?, restarting: Boolean) {
        super.onStartInputView(info, restarting)
        refreshKyrgyzAssociationSetting()
        applyEditorAction(info)
        syncStateFromEngine()
    }

    /** 依据输入框 imeOptions 决定回车键的动作与标签（搜索/发送/前往/下一项/完成，否则换行）。 */
    private fun applyEditorAction(info: android.view.inputmethod.EditorInfo?) {
        val imeOptions = info?.imeOptions ?: 0
        val rawAction = imeOptions and android.view.inputmethod.EditorInfo.IME_MASK_ACTION
        val noEnterAction =
            (imeOptions and android.view.inputmethod.EditorInfo.IME_FLAG_NO_ENTER_ACTION) != 0
        val hasAction = !noEnterAction &&
            rawAction != android.view.inputmethod.EditorInfo.IME_ACTION_NONE &&
            rawAction != android.view.inputmethod.EditorInfo.IME_ACTION_UNSPECIFIED
        if (hasAction) {
            editorAction = rawAction
            enterLabelState.value = when (rawAction) {
                android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH -> "\uD83D\uDD0D"
                android.view.inputmethod.EditorInfo.IME_ACTION_SEND -> "\u2191"
                android.view.inputmethod.EditorInfo.IME_ACTION_GO -> "\u2192"
                android.view.inputmethod.EditorInfo.IME_ACTION_NEXT -> "\u21E5"
                android.view.inputmethod.EditorInfo.IME_ACTION_DONE -> "\u2713"
                else -> "\u23CE"
            }
        } else {
            editorAction = null
            enterLabelState.value = null
        }
    }

    private fun refreshKyrgyzAssociationSetting() {
        val prefs = getSharedPreferences(
            SettingsRepository.PREFS_NAME,
            android.content.Context.MODE_PRIVATE
        )
        engine.kyrgyzAssociationEnabled =
            prefs.getBoolean(SettingsRepository.KEY_KYRGYZ_ASSOCIATION, false)
        keyFeedback.vibrateEnabled =
            prefs.getBoolean(SettingsRepository.KEY_VIBRATE, true)
        keyFeedback.soundEnabled =
            prefs.getBoolean(SettingsRepository.KEY_SOUND, false)
        fontSizeState.value =
            prefs.getFloat(SettingsRepository.KEY_FONT_SIZE, 18f)
    }

    private fun syncStateFromEngine() {
        languageState.value = engine.currentLanguage
        layoutState.value = engine.currentLayout
        kyrgyzShiftState.value = engine.kyrgyzShift
        englishShiftState.value = engine.englishShift
        composingState.value = engine.composing
        candidatesState.value = engine.candidates
    }

    override fun onDestroy() {
        lifecycleRegistry.currentState = Lifecycle.State.DESTROYED
        store.clear()
        super.onDestroy()
    }

    override fun onKeyPress(code: String) {
        currentInputConnection?.commitText(code, 1)
    }

    override fun onKeyAction(action: FunctionType) {
        val ic = currentInputConnection ?: return
        when (action) {
            FunctionType.SPACE -> ic.commitText(" ", 1)
            FunctionType.NEWLINE -> {
                val pendingAction = editorAction
                if (pendingAction != null) {
                    ic.performEditorAction(pendingAction)
                } else {
                    ic.commitText("\n", 1)
                }
            }
            FunctionType.BACKSPACE -> {
                val selected = ic.getSelectedText(0)
                if (!selected.isNullOrEmpty()) {
                    ic.commitText("", 1)
                } else {
                    // 删除一个可见字符；若其前面紧跟自动插入的双向控制符，则一并删除，避免残留
                    val before = ic.getTextBeforeCursor(2, 0)
                    val deleteCount = if (before != null && before.length == 2 &&
                        !BidiControls.isBidiControl(before[1]) &&
                        BidiControls.isBidiControl(before[0])
                    ) 2 else 1
                    ic.deleteSurroundingText(deleteCount, 0)
                }
            }
            FunctionType.DONE -> requestHideSelf(0)
            else -> Unit
        }
    }

    override fun onComposingChanged(composing: String) {
        val ic = currentInputConnection ?: return
        if (composing.isEmpty()) {
            ic.setComposingText("", 1)
            ic.finishComposingText()
        } else {
            ic.setComposingText(composing, 1)
        }
    }

    override fun onCommitCandidate(text: String) {
        val ic = currentInputConnection ?: return
        ic.commitText(text, 1)
    }

    override fun onDeleteBeforeCursor(count: Int) {
        if (count <= 0) return
        val ic = currentInputConnection ?: return
        ic.deleteSurroundingText(count, 0)
    }
}

@Composable
private fun KeyboardRoot(
    engine: KyrgyzKeyboardEngine,
    language: Language,
    layout: LayoutType,
    kyrgyzShift: Boolean,
    englishShift: Boolean,
    composing: String,
    candidates: List<String>,
    keyFontSize: Float,
    enterLabel: String?,
    onFeedback: () -> Unit,
    onStateChanged: () -> Unit
) {
    val rows = remember(language, layout, kyrgyzShift, englishShift) { engine.getRows() }
    val isRtl = language == Language.KYRGYZ
    val direction = if (isRtl) LayoutDirection.Rtl else LayoutDirection.Ltr

    CompositionLocalProvider(LocalLayoutDirection provides direction) {
        Surface(
            color = MaterialTheme.colorScheme.surface,
            modifier = Modifier.fillMaxWidth()
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(KeyboardTokens.BoardPadding),
                verticalArrangement = Arrangement.spacedBy(KeyboardTokens.RowGap)
            ) {
                // 候选栏：拼音模式常显；柯语模式在有输入/候选时显示（联想关闭时恒空不显示）
                if (language == Language.PINYIN ||
                    (language == Language.KYRGYZ && (composing.isNotEmpty() || candidates.isNotEmpty()))
                ) {
                    CandidateBar(
                        composing = composing,
                        candidates = candidates,
                        onPick = { idx ->
                            engine.selectCandidate(idx)
                            onStateChanged()
                        }
                    )
                }
                val onKey: (KyrgyzKey) -> Unit = remember(engine, onStateChanged) {
                    { k ->
                        engine.handleKey(k)
                        onStateChanged()
                    }
                }
                val onVariant: (String) -> Unit = remember(engine, onStateChanged) {
                    { v ->
                        engine.handleVariant(v)
                        onStateChanged()
                    }
                }
                val shiftActive = if (language == Language.KYRGYZ) kyrgyzShift else englishShift
                rows.forEachIndexed { rowIndex, row ->
                    key(language, layout, kyrgyzShift, englishShift, rowIndex) {
                        KeyboardRowView(
                            row = row,
                            fontSize = keyFontSize,
                            shiftActive = shiftActive,
                            shiftLocked = engine.shiftLocked,
                            onKey = onKey,
                            onVariant = onVariant,
                            onFeedback = onFeedback,
                            rowHeight = KeyboardTokens.RowHeight.value.toInt(),
                            enterLabel = enterLabel
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun CandidateBar(
    composing: String,
    candidates: List<String>,
    onPick: (Int) -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(KeyboardTokens.CandidateBarHeight)
            .clip(RoundedCornerShape(KeyboardTokens.CandidateBarCorner))
            .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = KeyboardTokens.CandidateBarBgAlpha))
    ) {
        if (composing.isEmpty() && candidates.isEmpty()) {
            Text(
                text = "输入显示候选",
                color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = KeyboardTokens.PlaceholderAlpha),
                fontSize = KeyboardTokens.CandidatePlaceholderSize,
                modifier = Modifier
                    .padding(horizontal = 12.dp)
                    .align(Alignment.CenterStart)
            )
        } else {
            val scroll = rememberScrollState()
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .horizontalScroll(scroll)
                    .padding(horizontal = 8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                if (composing.isNotEmpty()) {
                    Text(
                        text = composing,
                        color = MaterialTheme.colorScheme.primary,
                        fontSize = KeyboardTokens.CandidateComposingSize,
                        modifier = Modifier.padding(end = 12.dp)
                    )
                }
                candidates.forEachIndexed { i, cand ->
                    Box(
                        modifier = Modifier
                            .padding(horizontal = 4.dp)
                            .clip(RoundedCornerShape(KeyboardTokens.CandidateChipCorner))
                            .clickable { onPick(i) }
                            .padding(horizontal = 10.dp, vertical = 6.dp)
                    ) {
                        Text(
                            text = cand,
                            color = MaterialTheme.colorScheme.onPrimaryContainer,
                            fontSize = KeyboardTokens.CandidateWordSize
                        )
                    }
                }
            }
        }
    }
}

